    expect(typeof ns).toBe('number');\n    expect(ns!).toBeGreaterThan(0);\n  });\n\n  test('extractTextFromContent', () => {\n    expect(extractTextFromContent(undefined)).toBe('');\n    expect(extractTextFromContent('hi')).toBe('hi');\n    expect(\n      extractTextFromContent([\n        { type: 'input_text', text: 'a' },\n        { type: 'output_text', text: 'b' },\n      ] as any),\n    ).toBe('a\\nb');\n  });\n\n  test('readTranscript', () => {\n    const p = path.join(os.tmpdir(), 'rollout-smoke.jsonl');\n    const lines = [\n      { timestamp: '2025-01-01T00:00:00Z', type: 'session_meta', payload: { id: 's1', model: 'gpt-5' } },\n      { timestamp: '2025-01-01T00:00:01Z', type: 'event_msg', payload: { type: 'task_started' } },\n    ];\n    fs.writeFileSync(p, lines.map((l) => JSON.stringify(l)).join('\\n') + '\\n');\n    const recs = readTranscript(p);\n    expect(recs.length).toBe(2);\n    expect(recs[0].type).toBe('session_meta');\n  });\n\n  test('getModel / getSessionId / findLastUserPrompt', () => {\n    const recs: any[] = [\n      { timestamp: 't', type: 'session_meta', payload: { id: 'sess-9', model: 'gpt-5' } },\n      { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'user', content: [{ type: 'input_text', text: 'hello' }] } },\n    ];\n    expect(getModel(recs)).toBe('gpt-5');\n    expect(getModel([{ timestamp: 't', type: 'session_meta', payload: {} } as any])).toBe('unknown');\n    expect(getSessionId(recs)).toBe('sess-9');\n    expect(findLastUserPrompt(recs)!.text).toBe('hello');\n    expect(findLastUserPrompt([])).toBeNull();\n  });\n\n  test('getLastTurnRecords bounds', () => {\n    const recs: any[] = [\n      { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'user', content: [] } },\n      { timestamp: 't', type: 'event_msg', payload: { type: 'task_started' } },\n      { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'assistant', content: [{ type: 'output_text', text: 'x' }] } },\n      { timestamp: 't', type: 'event_msg', payload: { type: 'task_complete' } },\n    ];\n    const turn = getLastTurnRecords(recs);\n    expect(turn[0].type).toBe('event_msg');\n    expect((turn[0].payload as any).type).toBe('task_started');\n    expect((turn[turn.length - 1].payload as any).type).toBe('task_complete');\n  });\n\n  test('getTokenUsage / buildToolResultMap', () => {\n    const recs: any[] = [\n      { timestamp: 't', type: 'event_msg', payload: { type: 'token_count', info: { last_token_usage: { input_tokens: 5, output_tokens: 7, total_tokens: 12 } } } },\n      { timestamp: 't', type: 'response_item', payload: { type: 'function_call_output', call_id: 'c1', output: 'done' } },\n    ];\n    const usage = getTokenUsage(recs)!;\n    expect(usage.input_tokens).toBe(5);\n    expect(usage.output_tokens).toBe(7);\n    expect(usage.total_tokens).toBe(12);\n    expect(buildToolResultMap(recs)).toEqual({ c1: 'done' });\n    expect(buildToolResultMap([])).toEqual({});\n    expect(getTokenUsage([])).toBeNull();\n  });\n});\n\ndescribe('tracing helpers', () => {\n  test('reconstructMessages maps roles and skips empty', () => {\n    const items: any[] = [\n      { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'developer', content: [{ type: 'input_text', text: 'sys' }] } },\n      { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'user', content: [{ type: 'input_text', text: 'q' }] } },\n      { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'assistant', content: [{ type: 'output_text', text: '   ' }] } },\n      { timestamp: 't', type: 'response_item', payload: { type: 'function_call', name: 'exec', arguments: '{\"a\":1}', call_id: 'c1' } },\n      { timestamp: 't', type: 'response_item', payload: { type: 'function_call_output', call_id: 'c1', output: 'ok' } },\n    ];\n    const msgs = reconstructMessages(items, items.length);\n    expect(msgs).toEqual([\n      { role: 'system', content: 'sys' },\n      { role: 'user', content: 'q' },\n      { role: 'assistant', content: null, tool_calls: [{ id: 'c1', type: 'function', function: { name: 'exec', arguments: '{\"a\":1}' } }] },\n      { role: 'tool', tool_call_id: 'c1', content: 'ok' },\n    ]);\n  });\n\n  test('findTaskStartedNs / findTaskCompleteNs / buildToolStatuses', () => {\n    const turn: any[] = [\n      { timestamp: '2025-01-01T00:00:00Z', type: 'event_msg', payload: { type: 'task_started' } },\n      { timestamp: '2025-01-01T00:00:05Z', type: 'event_msg', payload: { type: 'exec_command_end', call_id: 'c1', status: 'failed', exit_code: 127 } },\n      { timestamp: '2025-01-01T00:00:06Z', type: 'event_msg', payload: { type: 'exec_command_end', call_id: 'c2', status: 'success', exit_code: 0 } },\n      { timestamp: '2025-01-01T00:00:10Z', type: 'event_msg', payload: { type: 'task_complete' } },\n    ];\n    expect(findTaskStartedNs(turn)).toBe(parseTimestampToNs('2025-01-01T00:00:00Z'));\n    expect(findTaskCompleteNs(turn)).toBe(parseTimestampToNs('2025-01-01T00:00:10Z'));\n    const st = buildToolStatuses(turn);\n    expect(st['c1'].failed).toBe(true);\n    expect(st['c1'].exitCode).toBe(127);\n    expect(st['c2'].failed).toBe(false);\n    expect(st['c2'].exitCode).toBe(0);\n  });\n});\n"],"version":3}
